int main() {
    // 1. Dynamic allocation with C++11 list initialization (value initialized to 0)
    int* rawArr = new int[3]{};
    std::cout << "rawArr values: " << rawArr[0] << " " << rawArr[1] << " " << rawArr[2] << "\n";
    delete[] rawArr; // Correct array deallocation

    // 2. Modern C++ RAII alternative using std::unique_ptr for arrays
    std::unique_ptr<int[]> smartArr = std::make_unique<int[]>(2);
    smartArr[0] = 42;
    smartArr[1] = 99;
    std::cout << "smartArr values: " << smartArr[0] << " " << smartArr[1] << "\n";
    // Automatically cleaned up via delete[] when smartArr leaves scope!

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Array {
    friend std::ostream& operator<<(std::ostream& output, const Array& a) {
        for (size_t i = 0; i < a.size; ++i) {
            output << std::setw(12) << a.ptr[i];
            if ((i + 1) % 4 == 0) output << '\n';
        }
        if (a.size % 4 != 0) output << '\n';
        return output;
    }

    friend std::istream& operator>>(std::istream& input, Array& a) {
        for (size_t i = 0; i < a.size; ++i) {
            input >> a.ptr[i];
        }
        return input;
    }

private:
    size_t size{0};
    int* ptr{nullptr};

public:
    explicit Array(int arraySize = 10) 
        : size{arraySize > 0 ? static_cast<size_t>(arraySize) : throw std::invalid_argument("Array size must be > 0")},
          ptr{new int[size]{}} {} // default initialized to 0

    Array(const Array& arrayToCopy) : size{arrayToCopy.size}, ptr{new int[size]} {
        for (size_t i = 0; i < size; ++i) {
            ptr[i] = arrayToCopy.ptr[i];
        }
    }

    ~Array() {
        delete[] ptr;
    }

    size_t getSize() const { return size; }

    const Array& operator=(const Array& right) {
        if (&right != this) {
            if (size != right.size) {
                delete[] ptr;
                size = right.size;
                ptr = new int[size];
            }
            for (size_t i = 0; i < size; ++i) {
                ptr[i] = right.ptr[i];
            }
        }
        return *this;
    }

    bool operator==(const Array& right) const {
        if (size != right.size) return false;
        for (size_t i = 0; i < size; ++i) {
            if (ptr[i] != right.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const Array& right) const {
        return !(*this == right);
    }

    int& operator[](int subscript) {
        if (subscript < 0 || static_cast<size_t>(subscript) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[subscript];
    }
};

int main() {
    Array integers1(7);
    Array integers2; // default 10 elements

    // Input 17 integers directly into both arrays via overloaded >>
    std::cin >> integers1 >> integers2;

    std::cout << "integers1 != integers2: " << (integers1 != integers2 ? "true" : "false") << '\n';

    Array integers3(integers1); // Copy constructor
    integers1 = integers2;      // Overloaded assignment
    std::cout << "integers1 == integers2: " << (integers1 == integers2 ? "true" : "false") << '\n';

    // Subscript lvalue and out_of_range check
    integers1[5] = 1000;
    std::cout << "integers1[5] is " << integers1[5] << '\n';

    try {
        integers1[15] = 1000;
    } catch (const std::out_of_range& ex) {
        std::cout << "An exception occurred: " << ex.what() << '\n';
    }

    return 0;
}
